import json, re
from collections import defaultdict
cat = defaultdict(float)
with open('er013_output/family_c_episode_trial_09/home_robots/raw_usage_log.jsonl', encoding='utf-8') as f:
    for line in f:
        r = json.loads(line)
        label = r['label']
        if 'key_phrases_selection_pipeline' in label:
            cat['Key Phrase選定パイプライン(LLM: 選定/canonicalization/redundancy QA)'] += r['jpy_estimate']
        elif label in ('preview_llm','support_1_llm','support_2_llm'):
            cat['Preview/Support LLM生成'] += r['jpy_estimate']
        elif label.startswith('kp') and label.endswith('_english'):
            cat['Key Phrase英語Component TTS'] += r['jpy_estimate']
        elif label.startswith('kp') and label.endswith('_japanese'):
            cat['Key Phrase日本語gloss TTS'] += r['jpy_estimate']
        elif label.startswith('story_'):
            cat['物語本文 TTS(narrator+robot)'] += r['jpy_estimate']
        elif label in ('topic_intro_en','topic_intro_ja','preview_ja','support_1_ja','support_2_ja'):
            cat['topic_intro/preview/support TTS'] += r['jpy_estimate']
        else:
            cat['other:'+label] += r['jpy_estimate']
for k,v in sorted(cat.items(), key=lambda x:-x[1]):
    print(f'{v:7.2f}  {k}')
print('TOTAL', round(sum(cat.values()),2))
"

